"""Evaluation metrics for SVEAD."""
import numpy as np
from sklearn.metrics import roc_auc_score, average_precision_score, precision_recall_curve


def roc_auc(scores: np.ndarray, labels: np.ndarray) -> float:
    """Compute AUC-ROC."""
    return float(roc_auc_score(labels, scores))


def auc_pr(scores: np.ndarray, labels: np.ndarray) -> float:
    """Compute AUC-PR (average precision)."""
    return float(average_precision_score(labels, scores))


def auc_pr_trapezoidal(scores: np.ndarray, labels: np.ndarray) -> float:
    """Compute AUC-PR via trapezoidal rule on the precision-recall curve."""
    prec, rec, _ = precision_recall_curve(labels, scores)
    # trapezoidal rule
    return float(np.trapz(prec, rec))


def summarize(values: list) -> dict:
    """Return mean/std/min/max for a list of numbers."""
    arr = np.asarray(values, dtype=np.float64)
    return {
        "mean": float(arr.mean()),
        "std": float(arr.std()),
        "min": float(arr.min()),
        "max": float(arr.max()),
    }


def evaluate_scores(
    scores: np.ndarray,
    labels: np.ndarray,
) -> dict:
    """
    Compute all metrics for a single run.

    Parameters
