    scores : np.ndarray, shape (n,)
    labels : np.ndarray, shape (n,)

    Returns
    -------
    dict with auc_roc, auc_pr, auc_pr_trap
    """
    return {
        "auc_roc": roc_auc(scores, labels),
        "auc_pr": auc_pr(scores, labels),
        "auc_pr_trap": auc_pr_trapezoidal(scores, labels),
    }

